+
+      function App() {
+        return SupportContactForm();
+      }
+
+      function render() {
+        document.getElementById("root").innerHTML = App();
+        attachFormEvents();
+      }
+
+      function syncFormValues(form) {
+        formState.values.fullName = form.fullName.value;
+        formState.values.email = form.email.value;
+        formState.values.phone = form.phone.value;
+      }
+
