+            nextField.setSelectionRange(nextField.value.length, nextField.value.length);
+          }
+        });
+
+        form.addEventListener("submit", (event) => {
+          event.preventDefault();
+          syncFormValues(form);
+          formState.errors = validate(formState.values);
+          formState.submitted = true;
+          render();
+        });
+      }
+
+      render();
+    </script>
+  </body>
+</html>
