  <body>
    <div id="root"></div>

    <script>
      const formState = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        errors: {},
        submitted: false,
      };

      const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      function escapeHtml(value) {
        return value
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#39;");
      }

      function validate(values) {
        const errors = {};

        if (!values.fullName.trim()) {
          errors.fullName = "Full name is required.";
        }

        if (!values.email.trim()) {
          errors.email = "Email address is required.";
        } else if (!emailPattern.test(values.email.trim())) {
          errors.email = "Enter a valid email address.";
        }

        if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
          errors.phone = "Enter a valid phone number in the expected format.";
        }

        return errors;
      }

      function FormField({ id, label, type, value, placeholder, required, helperText, error }) {
        const describedBy = [
          helperText ? id + "-help" : "",
          error ? id + "-error" : "",
        ]
          .filter(Boolean)
          .join(" ");

        return `
          <div class="form-field">
            <label for="${id}">
              ${label}${required ? ' <span class="field-meta">(required)</span>' : ""}
            </label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              value="${escapeHtml(value)}"
              placeholder="${placeholder}"
              ${required ? "required" : ""}
              aria-invalid="${error ? "true" : "false"}"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            />
            ${helperText ? `<span id="${id}-help" class="helper-text">${helperText}</span>` : ""}
            ${
              error
                ? `<span id="${id}-error" class="validation-message" role="alert">${error}</span>`
                : ""
            }
          </div>
        `;
      }

      function SupportContactForm() {
        const { values, errors, submitted } = formState;

        return `
          <div class="page-shell">
            <section class="card">
              <p class="eyebrow">Support</p>
              <h1>Contact our support team</h1>
              <p class="intro">
                Share your issue and we will reach out with the next steps as soon as possible.
              </p>
              <form id="support-form" novalidate>
                ${FormField({
                  id: "fullName",
                  label: "Full name",
                  type: "text",
                  value: values.fullName,
                  placeholder: "Jordan Lee",
                  required: true,
                  error: errors.fullName,
                })}
                ${FormField({
                  id: "email",
                  label: "Email address",
                  type: "email",
                  value: values.email,
                  placeholder: "jordan@example.com",
                  required: true,
                  error: errors.email,
                })}
                ${FormField({
                  id: "phone",
                  label: "Phone number",
                  type: "tel",
                  value: values.phone,
                  placeholder: "+1 (555) 123-4567",
                  required: false,
                  helperText: "Optional. Use digits, spaces, dashes, parentheses, and an optional leading +.",
                  error: errors.phone,
                })}
                <button class="submit-button" type="submit">Submit</button>
                ${
                  submitted && Object.keys(errors).length === 0
                    ? '<div class="success-message" role="status">Thanks. Your support request is ready to send.</div>'
                    : ""
                }
              </form>
            </section>
          </div>
        `;
      }

      function App() {
        return SupportContactForm();
      }

      function render() {
        document.getElementById("root").innerHTML = App();
        attachFormEvents();
      }

      function syncFormValues(form) {
        formState.values.fullName = form.fullName.value;
        formState.values.email = form.email.value;
        formState.values.phone = form.phone.value;
      }

      function attachFormEvents() {
        const form = document.getElementById("support-form");

        form.addEventListener("input", (event) => {
          syncFormValues(form);
          const fieldName = event.target.name;
          const nextErrors = validate(formState.values);
          formState.errors = {
            ...formState.errors,
            [fieldName]: nextErrors[fieldName],
          };
          formState.submitted = false;
          render();
          const nextField = document.getElementById(fieldName);
          if (nextField) {
            nextField.focus();
            nextField.setSelectionRange(nextField.value.length, nextField.value.length);
          }
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          syncFormValues(form);
          formState.errors = validate(formState.values);
          formState.submitted = true;
          render();
        });
      }

      render();
    </script>
  </body>
